            if (SpeedKmh < 78f) return 1;
            if (SpeedKmh < 122f) return 2;
            if (SpeedKmh < 164f) return 3;
            if (SpeedKmh < 204f) return 4;
            if (SpeedKmh < 244f) return 5;
            if (SpeedKmh < 282f) return 6;
            if (SpeedKmh < 316f) return 7;
            return 8;
        }
