    private (Node3D steerPivot, Node3D spinNode) BuildWheelAssembly(
        float side,
        float radius,
        float width,
        StandardMaterial3D rubberMat,
        StandardMaterial3D sidewallMat,
        StandardMaterial3D carbonMat,
        bool isFront)
    {
        var steerPivot = new Node3D();
        var spinNode = new Node3D();
        steerPivot.AddChild(spinNode);

        // Rounded-shoulder 3D tire tread
        spinNode.AddChild(new MeshInstance3D
        {
            Mesh = MeshPrimitives3D.CreateRevolvedTireTread(radius, width, 28),
            MaterialOverride = rubberMat
        });
        // Outer & inner textured Pirelli sidewalls with spinning red compound ring & carbon wheel cover
        spinNode.AddChild(new MeshInstance3D
        {
            Mesh = MeshPrimitives3D.CreateTireSidewallDisc(radius * 0.85f, side * width * 0.5f, side, 28),
            MaterialOverride = sidewallMat
        });
        spinNode.AddChild(new MeshInstance3D
        {
            Mesh = MeshPrimitives3D.CreateTireSidewallDisc(radius * 0.85f, -side * width * 0.5f, -side, 28),
            MaterialOverride = sidewallMat
        });

        if (isFront)
        {
            // Non-spinning inner Carbon Brake Duct & Glowing Thermal Brake Rotor
            steerPivot.AddChild(new MeshInstance3D
            {
                Mesh = new CylinderMesh { TopRadius = radius * 0.54f, BottomRadius = radius * 0.54f, Height = 0.06f, RadialSegments = 16 },
                Position = new Vector3(-side * (width * 0.52f), 0f, 0f),
                RotationDegrees = new Vector3(0f, 0f, 90f),
                MaterialOverride = carbonMat
            });
            steerPivot.AddChild(new MeshInstance3D
            {
                Mesh = new CylinderMesh { TopRadius = radius * 0.44f, BottomRadius = radius * 0.44f, Height = 0.025f, RadialSegments = 16 },
                Position = new Vector3(-side * (width * 0.54f), 0f, 0f),
                RotationDegrees = new Vector3(0f, 0f, 90f),
                MaterialOverride = _brakeGlowMat
            });
            // Iconic 2024 F1 Curved Carbon Over-Wheel Aero Brow Winglet!
            Vector3[] browPath =
            {
                new(-side * (width * 0.54f), radius * 0.12f, -radius * 0.72f),
                new(-side * (width * 0.56f), radius * 0.84f, -radius * 0.44f),
                new(-side * (width * 0.52f), radius * 1.07f,  radius * 0.14f)
            };
            steerPivot.AddChild(new MeshInstance3D
            {
                Mesh = MeshPrimitives3D.CreateTubeAlongPath(browPath, new[] { 0.012f, 0.016f, 0.012f }, new[] { 0.048f, 0.065f, 0.045f }, 8),
                MaterialOverride = carbonMat
            });
        }

        return (steerPivot, spinNode);
    }

    public override void _PhysicsProcess(double delta)
    {
        if (_track == null) return;
        float dt = (float)delta;
        _totalTime += dt;

        bool left = InputLeft || Input.IsKeyPressed(Key.Left) || Input.IsKeyPressed(Key.A);
        bool right = InputRight || Input.IsKeyPressed(Key.Right) || Input.IsKeyPressed(Key.D);
        bool gas = InputGas || Input.IsKeyPressed(Key.Up) || Input.IsKeyPressed(Key.W);
        bool brake = InputBrake || Input.IsKeyPressed(Key.Down) || Input.IsKeyPressed(Key.S);

        float prevSpeed = SpeedKmh;
        bool ersActive = ErsEnabled && ErsCharge > 1f && gas && !brake;
        if (ersActive)
        {
            ErsCharge = Mathf.Max(0f, ErsCharge - 20f * dt);
            if (ErsCharge <= 1f) ErsEnabled = false;
        }
        else
        {
            float regen = brake ? 22f : 6f;
            ErsCharge = Mathf.Min(100f, ErsCharge + regen * dt);
        }

        float maxSpeed = ersActive ? 355f : 318f;
        IsOffTrack = Mathf.Abs(LateralOffset) > TrackBuilder3D.TrackHalfWidth + 0.55f;
        if (gas && !brake)
        {
            float accel = ersActive ? 172f : 124f;
            if (IsOffTrack) accel *= 0.56f;
            SpeedKmh = Mathf.Min(maxSpeed, SpeedKmh + accel * dt);
        }
        else if (brake)
        {
            SpeedKmh = Mathf.Max(0f, SpeedKmh - 215f * dt);
            ErsEnabled = false;
        }
        else
        {
            SpeedKmh = Mathf.Max(0f, SpeedKmh - (36f + SpeedKmh * 0.09f) * dt);
        }

        if (IsOffTrack && SpeedKmh > 132f)
        {
            SpeedKmh = Mathf.Max(132f, SpeedKmh - 55f * dt);
        }

        float targetSteer = (right ? 1f : 0f) - (left ? 1f : 0f);
        float steerRate = Mathf.Abs(targetSteer) > 0.01f ? 12.0f : 17.0f;
        SteerAngle = Mathf.Lerp(SteerAngle, targetSteer, 1f - Mathf.Exp(-steerRate * dt));

        TrackSample sample = _track.SampleAtDistance(TrackDistance);
        float vMs = SpeedKmh / 3.6f;
        float speedFactor = Mathf.Clamp(SpeedKmh / 20f, 0f, 1f);
        float manualYawRate = SteerAngle * (1.88f / (1.0f + SpeedKmh * 0.0044f)) * speedFactor;
        float roadYawRate = vMs * sample.Curvature;

        HeadingOffset += (manualYawRate - roadYawRate) * dt;
        if (Mathf.Abs(targetSteer) < 0.01f && Mathf.Abs(sample.Curvature) < 0.004f)
        {
            HeadingOffset *= Mathf.Exp(-6.8f * dt);
        }
        HeadingOffset = Mathf.Clamp(HeadingOffset, -0.58f, 0.58f);

        LateralOffset += vMs * Mathf.Sin(HeadingOffset) * dt;
        float maxLat = TrackBuilder3D.BarrierOffset - 1.15f;
        if (Mathf.Abs(LateralOffset) > maxLat)
        {
            LateralOffset = Mathf.Sign(LateralOffset) * maxLat;
            HeadingOffset *= -0.25f;
            SpeedKmh *= 0.72f;
        }

        TrackDistance += Mathf.Max(0f, vMs * Mathf.Cos(HeadingOffset)) * dt;
        CurrentLapTime += dt;

        if (TrackDistance >= _track.TotalLength)
        {
            TrackDistance -= _track.TotalLength;
            if (CurrentLapTime > 5.0f && CurrentLapTime < BestLapTime)
            {
                BestLapTime = CurrentLapTime;
            }
            CurrentLap++;
            CurrentLapTime = 0f;
        }

        // G-Force Helmet Inertia, Brake Disc Glow & Tire Thermal State
        float rawLatG = Mathf.Clamp((manualYawRate * vMs) / 42f, -1.0f, 1.0f);
        float rawLongG = Mathf.Clamp(((SpeedKmh - prevSpeed) / Mathf.Max(dt, 0.005f)) / 185f, -1.0f, 1.0f);
        _smoothLatG = Mathf.Lerp(_smoothLatG, rawLatG, 1f - Mathf.Exp(-8.5f * dt));
        _smoothLongG = Mathf.Lerp(_smoothLongG, rawLongG, 1f - Mathf.Exp(-7.5f * dt));

        float targetBrakeHeat = (brake && SpeedKmh > 40f) ? Mathf.Clamp(SpeedKmh / 220f, 0.35f, 1.0f) : 0f;
        _smoothBrakeHeat = Mathf.Lerp(_smoothBrakeHeat, targetBrakeHeat, 1f - Mathf.Exp(-(targetBrakeHeat > _smoothBrakeHeat ? 6.5f : 1.8f) * dt));
        _brakeGlowMat.EmissionEnergyMultiplier = _smoothBrakeHeat * 4.2f;

        float targetTireHeat = Mathf.Clamp(0.36f + Mathf.Abs(_smoothLatG) * 0.45f + _smoothBrakeHeat * 0.25f, 0.25f, 1.0f);
        _smoothTireHeat = Mathf.Lerp(_smoothTireHeat, targetTireHeat, 1f - Mathf.Exp(-1.2f * dt));

        // Animate 3D Steering Wheel, 4 Spinning Pirelli Wheels & Live MFD Telemetry
        _steeringWheel.RotationDegrees = new Vector3(-16f, 0f, -SteerAngle * 56f);
        _wheelRoll -= vMs * dt / 0.34f;
        _frontLeftSteering.Rotation = new Vector3(0f, -SteerAngle * 0.35f, 0f);
        _frontRightSteering.Rotation = new Vector3(0f, -SteerAngle * 0.35f, 0f);
        _frontLeftSpin.Rotation = new Vector3(_wheelRoll, 0f, 0f);
        _frontRightSpin.Rotation = new Vector3(_wheelRoll, 0f, 0f);
        _rearLeftSpin.Rotation = new Vector3(_wheelRoll * 0.94f, 0f, 0f);
        _rearRightSpin.Rotation = new Vector3(_wheelRoll * 0.94f, 0f, 0f);

        // Authentic Cockpit Camera G-Force Sway, Kerb Rumble & Dynamic Speed FOV
        bool onKerb = Mathf.Abs(LateralOffset) > TrackBuilder3D.TrackHalfWidth - 0.15f && Mathf.Abs(LateralOffset) < TrackBuilder3D.TrackHalfWidth + 1.15f;
        float rumbleY = (onKerb || IsOffTrack) && SpeedKmh > 30f ? Mathf.Sin(_totalTime * 42f) * 0.008f : Mathf.Sin(_totalTime * 18f) * (SpeedKmh / 355f) * 0.0018f;
        _cockpitCam.Position = new Vector3(-_smoothLatG * 0.022f, 0.745f + rumbleY - _smoothLongG * 0.008f, -0.155f + _smoothLongG * 0.015f);
        _cockpitCam.RotationDegrees = new Vector3(-8.0f + _smoothLongG * 1.4f, -_smoothLatG * 2.2f, _smoothLatG * 2.6f);
        _cockpitCam.Fov = Mathf.Lerp(_cockpitCam.Fov, 70f + (SpeedKmh / 355f) * 10f + (ersActive ? 4f : 0f), 1f - Mathf.Exp(-6f * dt));

        _steeringWheel.UpdateTelemetry(
            dt,
            SpeedKmh,
            Gear,
            RpmNormalized,
            CurrentLapTime,
            BestLapTime,
            ErsCharge,
            ersActive,
            IsOffTrack,
            _smoothTireHeat,
            _totalTime);

        ApplyTransform();
    }

    private void ApplyTransform()
    {
        TrackSample s = _track.SampleAtDistance(TrackDistance);
        Position = s.Center + s.Right * LateralOffset + Vector3.Up * 0.04f;
        Basis trackBasis = Basis.LookingAt(s.Forward, Vector3.Up);
        Basis = trackBasis.Rotated(Vector3.Up, -HeadingOffset);
    }
}

