using Godot;
using System.Collections.Generic;

namespace ApexGP24;

public partial class TouchHud : CanvasLayer
{
    private PlayerCar3D _car;

    private Label _speedLbl;
    private Label _gearLbl;
    private Label _lapLbl;
    private Label _ersLbl;
    private ColorRect _rpmFill;

    private Panel _btnLeft;
    private Panel _btnRight;
    private Panel _btnBrake;
    private Panel _btnGas;
    private Panel _btnErs;

    private readonly Dictionary<int, Vector2> _activeTouches = new();

    public void Initialize(PlayerCar3D car)
    {
        _car = car;
        BuildUi();
    }

    private void BuildUi()
    {
        var root = new Control();
        root.SetAnchorsPreset(Control.LayoutPreset.FullRect);
        root.MouseFilter = Control.MouseFilterEnum.Ignore;
        AddChild(root);

        // Top-Left Lap & Position Telemetry Card
        var topLeft = CreateCard(new Vector2(18, 14), new Vector2(230, 74), new Color(0.03f, 0.05f, 0.09f, 0.82f), new Color(0.88f, 0.07f, 0.06f));
        root.AddChild(topLeft);

        _lapLbl = CreateLabel("VTA 1  •  00.000", 17, Colors.White);
        _lapLbl.Position = new Vector2(12, 10);
        topLeft.AddChild(_lapLbl);

        var subLbl = CreateLabel("V2 COCKPIT MFD 3D  •  C# .NET 8", 11, new Color(0.45f, 0.90f, 1.0f));
        subLbl.Position = new Vector2(12, 42);
        topLeft.AddChild(subLbl);

        // Top-Right Speed / Gear / RPM Card + Camera & Reset Buttons
        var topRight = CreateCard(new Vector2(1012, 14), new Vector2(250, 90), new Color(0.03f, 0.05f, 0.09f, 0.84f), new Color(0.25f, 0.35f, 0.50f));
        topRight.SetAnchorsPreset(Control.LayoutPreset.TopRight);
        topRight.Position = new Vector2(-266, 14);
        root.AddChild(topRight);

        var rpmBg = new ColorRect { Color = new Color(0.12f, 0.16f, 0.24f), Position = new Vector2(12, 10), Size = new Vector2(226, 8) };
        topRight.AddChild(rpmBg);
        _rpmFill = new ColorRect { Color = new Color(0.0f, 0.90f, 0.45f), Position = new Vector2(12, 10), Size = new Vector2(40, 8) };
        topRight.AddChild(_rpmFill);

        _speedLbl = CreateLabel("0 KM/H", 26, Colors.White);
        _speedLbl.Position = new Vector2(12, 24);
        topRight.AddChild(_speedLbl);

        _gearLbl = CreateLabel("G1", 28, new Color(1.0f, 0.84f, 0.28f));
        _gearLbl.Position = new Vector2(182, 22);
        topRight.AddChild(_gearLbl);

        _ersLbl = CreateLabel("ERS 100%", 13, new Color(0.0f, 0.90f, 1.0f));
        _ersLbl.Position = new Vector2(12, 62);
        topRight.AddChild(_ersLbl);

        // Camera & Reset buttons at Top Center
        var camBtn = new Button { Text = "CÁMARA", Position = new Vector2(475, 16), Size = new Vector2(100, 38) };
        camBtn.Pressed += () => _car.ToggleCamera();
        root.AddChild(camBtn);

        var teamBtn = new Button { Text = "EQUIPO", Position = new Vector2(585, 16), Size = new Vector2(100, 38) };
        teamBtn.Pressed += () => _car.CycleLivery();
        root.AddChild(teamBtn);

        var resetBtn = new Button { Text = "REINICIAR", Position = new Vector2(695, 16), Size = new Vector2(100, 38) };
        resetBtn.Pressed += () => _car.ResetCar();
        root.AddChild(resetBtn);

        // Bottom-Left Multi-Touch Steering Pads (< and >)
        _btnLeft = CreateControlPad("<", new Vector2(24, -148), new Vector2(138, 124), Control.LayoutPreset.BottomLeft, new Color(0.08f, 0.13f, 0.22f, 0.78f), new Color(0.0f, 0.88f, 1.0f));
        root.AddChild(_btnLeft);

        _btnRight = CreateControlPad(">", new Vector2(178, -148), new Vector2(138, 124), Control.LayoutPreset.BottomLeft, new Color(0.08f, 0.13f, 0.22f, 0.78f), new Color(0.0f, 0.88f, 1.0f));
        root.AddChild(_btnRight);

        // Bottom-Right Multi-Touch Pedals (FRENO + GAS) & ERS Toggle
        _btnErs = CreateControlPad("ERS / OVERTAKE", new Vector2(-216, -214), new Vector2(190, 52), Control.LayoutPreset.BottomRight, new Color(0.06f, 0.24f, 0.42f, 0.84f), new Color(0.0f, 0.90f, 1.0f), 15);
        root.AddChild(_btnErs);

        _btnBrake = CreateControlPad("FRENO", new Vector2(-248, -144), new Vector2(106, 118), Control.LayoutPreset.BottomRight, new Color(0.42f, 0.08f, 0.10f, 0.82f), new Color(1.0f, 0.35f, 0.35f), 18);
        root.AddChild(_btnBrake);

        _btnGas = CreateControlPad("GAS", new Vector2(-126, -158), new Vector2(100, 132), Control.LayoutPreset.BottomRight, new Color(0.07f, 0.36f, 0.18f, 0.84f), new Color(0.0f, 0.92f, 0.46f), 20);
        root.AddChild(_btnGas);
    }

    public override void _Input(InputEvent @event)
    {
        if (_car == null) return;

        if (@event is InputEventScreenTouch touch)
        {
            if (touch.Pressed)
            {
                if (_btnErs.GetGlobalRect().HasPoint(touch.Position))
                {
                    _car.ErsEnabled = !_car.ErsEnabled;
                }
                _activeTouches[touch.Index] = touch.Position;
            }
            else
            {
                _activeTouches.Remove(touch.Index);
            }
            SyncTouchControls();
        }
        else if (@event is InputEventScreenDrag drag)
        {
            _activeTouches[drag.Index] = drag.Position;
            SyncTouchControls();
        }
    }

    private void SyncTouchControls()
    {
        bool left = false, right = false, brake = false, gas = false;
        foreach (Vector2 pos in _activeTouches.Values)
        {
            if (_btnLeft.GetGlobalRect().HasPoint(pos)) left = true;
            if (_btnRight.GetGlobalRect().HasPoint(pos)) right = true;
            if (_btnBrake.GetGlobalRect().HasPoint(pos)) brake = true;
            if (_btnGas.GetGlobalRect().HasPoint(pos)) gas = true;
        }
        _car.InputLeft = left;
        _car.InputRight = right;
        _car.InputBrake = brake;
        _car.InputGas = gas;
    }

    public override void _Process(double delta)
    {
        if (_car == null) return;
        _speedLbl.Text = $"{(int)_car.SpeedKmh} KM/H";
        _gearLbl.Text = $"G{_car.Gear}";
        string bestStr = _car.BestLapTime < 900f ? $"  •  MEJOR {_car.BestLapTime:00.00}" : "";
        _lapLbl.Text = $"VTA {_car.CurrentLap}  •  {_car.CurrentLapTime:00.00}{bestStr}";
        _ersLbl.Text = _car.ErsEnabled ? $"ERS ACTIVO {(int)_car.ErsCharge}%" : $"ERS {(int)_car.ErsCharge}%";

        float rpm = _car.RpmNormalized;
        _rpmFill.Size = new Vector2(Mathf.Max(6f, 226f * rpm), 8f);
        _rpmFill.Color = rpm > 0.85f ? new Color(0.20f, 0.55f, 1.0f) : (rpm > 0.58f ? new Color(1.0f, 0.16f, 0.20f) : new Color(0.0f, 0.90f, 0.45f));
    }

    private static Panel CreateCard(Vector2 pos, Vector2 size, Color bg, Color border)
    {
        var p = new Panel { Position = pos, Size = size, MouseFilter = Control.MouseFilterEnum.Ignore };
        var sb = new StyleBoxFlat
        {
            BgColor = bg,
            BorderColor = border,
            BorderWidthLeft = 2, BorderWidthRight = 2, BorderWidthTop = 2, BorderWidthBottom = 2,
            CornerRadiusTopLeft = 12, CornerRadiusTopRight = 12, CornerRadiusBottomLeft = 12, CornerRadiusBottomRight = 12
        };
        p.AddThemeStyleboxOverride("panel", sb);
        return p;
    }

    private static Panel CreateControlPad(string text, Vector2 offset, Vector2 size, Control.LayoutPreset preset, Color bg, Color border, int fontSize = 36)
    {
        var p = CreateCard(Vector2.Zero, size, bg, border);
        p.SetAnchorsPreset(preset);
        p.Position = offset;

        var lbl = CreateLabel(text, fontSize, Colors.White);
        lbl.SetAnchorsPreset(Control.LayoutPreset.FullRect);
        lbl.HorizontalAlignment = HorizontalAlignment.Center;
        lbl.VerticalAlignment = VerticalAlignment.Center;
        p.AddChild(lbl);
        return p;
    }

    private static Label CreateLabel(string text, int fontSize, Color color)
    {
        var lbl = new Label { Text = text, MouseFilter = Control.MouseFilterEnum.Ignore };
        lbl.AddThemeFontSizeOverride("font_size", fontSize);
        lbl.AddThemeColorOverride("font_color", color);
        return lbl;
    }
}

