using Godot;
using System;
using System.Collections.Generic;

namespace ApexGP24;

public static class MeshPrimitives3D
{
    // Helper: adds a quad with Godot front-face CLOCKWISE winding matching outward normal `hintNormal`
    private static void AddOrientedQuad(
        SurfaceTool st,
        Vector3 a, Vector3 b, Vector3 c, Vector3 d,
        Vector2 uvA, Vector2 uvB, Vector2 uvC, Vector2 uvD,
        Vector3 hintNormal)
    {
        // Godot front face normal for triangle (a, b, c) is (c - a).Cross(b - a)
        Vector3 n = (c - a).Cross(b - a);
        if (n.Dot(hintNormal) >= 0f)
        {
            st.SetUV(uvA); st.AddVertex(a);
            st.SetUV(uvB); st.AddVertex(b);
            st.SetUV(uvC); st.AddVertex(c);

            st.SetUV(uvA); st.AddVertex(a);
            st.SetUV(uvC); st.AddVertex(c);
            st.SetUV(uvD); st.AddVertex(d);
        }
        else
        {
            st.SetUV(uvA); st.AddVertex(a);
            st.SetUV(uvC); st.AddVertex(c);
            st.SetUV(uvB); st.AddVertex(b);

            st.SetUV(uvA); st.AddVertex(a);
            st.SetUV(uvD); st.AddVertex(d);
            st.SetUV(uvC); st.AddVertex(c);
        }
    }

    /// <summary>
    /// Creates a rounded-shoulder 18-inch F1 Pirelli slick tire tread mesh revolved around the X-axis.
    /// </summary>
    public static ArrayMesh CreateRevolvedTireTread(float radius, float width, int radialSteps = 28)
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        float hw = width * 0.5f;
        // Rounded F1 slick shoulder profile: (x offset, radial factor)
        (float x, float r)[] profile =
        {
            (-hw, radius * 0.84f),
            (-hw * 0.96f, radius * 0.95f),
            (-hw * 0.82f, radius * 0.995f),
            (-hw * 0.45f, radius * 1.00f),
            (0f, radius * 1.005f),
            (hw * 0.45f, radius * 1.00f),
            (hw * 0.82f, radius * 0.995f),
            (hw * 0.96f, radius * 0.95f),
            (hw, radius * 0.84f)
        };

        for (int p = 0; p < profile.Length - 1; p++)
        {
            float u0 = p / (float)(profile.Length - 1);
            float u1 = (p + 1) / (float)(profile.Length - 1);
            for (int i = 0; i < radialSteps; i++)
            {
                float a0 = (i / (float)radialSteps) * Mathf.Tau;
                float a1 = ((i + 1) / (float)radialSteps) * Mathf.Tau;
                float v0 = (i / (float)radialSteps) * 3.0f;
                float v1 = ((i + 1) / (float)radialSteps) * 3.0f;

                Vector3 p00 = new Vector3(profile[p].x, Mathf.Sin(a0) * profile[p].r, Mathf.Cos(a0) * profile[p].r);
                Vector3 p10 = new Vector3(profile[p + 1].x, Mathf.Sin(a0) * profile[p + 1].r, Mathf.Cos(a0) * profile[p + 1].r);
                Vector3 p11 = new Vector3(profile[p + 1].x, Mathf.Sin(a1) * profile[p + 1].r, Mathf.Cos(a1) * profile[p + 1].r);
                Vector3 p01 = new Vector3(profile[p].x, Mathf.Sin(a1) * profile[p].r, Mathf.Cos(a1) * profile[p].r);

                float am = (a0 + a1) * 0.5f;
                Vector3 outDir = new Vector3(0f, Mathf.Sin(am), Mathf.Cos(am));
                AddOrientedQuad(st, p00, p10, p11, p01, new Vector2(u0, v0), new Vector2(u1, v0), new Vector2(u1, v1), new Vector2(u0, v1), outDir);
            }
        }

        st.GenerateNormals();
        st.GenerateTangents();
        return st.Commit();
    }

    /// <summary>
    /// Creates a flat textured circular sidewall disc on +X or -X side of the tire (for Pirelli compound markings & wheel covers).
    /// </summary>
    public static ArrayMesh CreateTireSidewallDisc(float radius, float xPos, float xDir, int radialSteps = 28)
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        Vector3 center = new Vector3(xPos, 0f, 0f);
        Vector2 uvCenter = new Vector2(0.5f, 0.5f);
        Vector3 normal = new Vector3(xDir, 0f, 0f);

        for (int i = 0; i < radialSteps; i++)
        {
            float a0 = (i / (float)radialSteps) * Mathf.Tau;
            float a1 = ((i + 1) / (float)radialSteps) * Mathf.Tau;

            Vector3 p0 = new Vector3(xPos, Mathf.Sin(a0) * radius, Mathf.Cos(a0) * radius);
            Vector3 p1 = new Vector3(xPos, Mathf.Sin(a1) * radius, Mathf.Cos(a1) * radius);
            Vector2 uv0 = new Vector2(0.5f + Mathf.Cos(a0) * 0.5f, 0.5f + Mathf.Sin(a0) * 0.5f);
            Vector2 uv1 = new Vector2(0.5f + Mathf.Cos(a1) * 0.5f, 0.5f + Mathf.Sin(a1) * 0.5f);

            Vector3 triN = (p1 - center).Cross(p0 - center);
            if (triN.Dot(normal) >= 0f)
            {
                st.SetUV(uvCenter); st.AddVertex(center);
                st.SetUV(uv0); st.AddVertex(p0);
                st.SetUV(uv1); st.AddVertex(p1);
            }
            else
            {
                st.SetUV(uvCenter); st.AddVertex(center);
                st.SetUV(uv1); st.AddVertex(p1);
                st.SetUV(uv0); st.AddVertex(p0);
            }
        }

        st.GenerateNormals();
        return st.Commit();
    }

    /// <summary>
    /// Sweeps a smooth oval/tubular 3D cross-section along an arbitrary 3D path (ideal for F1 Halo hoop, central pillar & stalks).
    /// </summary>
    public static ArrayMesh CreateTubeAlongPath(Vector3[] path, float[] rxList, float[] ryList, int ringSegs = 12)
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        int n = path.Length;
        Vector3[][] rings = new Vector3[n][];

        for (int i = 0; i < n; i++)
        {
            Vector3 tangent;
            if (i == 0) tangent = (path[1] - path[0]).Normalized();
            else if (i == n - 1) tangent = (path[n - 1] - path[n - 2]).Normalized();
            else tangent = (path[i + 1] - path[i - 1]).Normalized();

            Vector3 upRef = Mathf.Abs(tangent.Dot(Vector3.Up)) > 0.94f ? Vector3.Forward : Vector3.Up;
            Vector3 side = tangent.Cross(upRef).Normalized();
            Vector3 up = side.Cross(tangent).Normalized();

            rings[i] = new Vector3[ringSegs];
            float rx = rxList[i];
            float ry = ryList[i];
            for (int r = 0; r < ringSegs; r++)
            {
                float a = (r / (float)ringSegs) * Mathf.Tau;
                rings[i][r] = path[i] + side * (Mathf.Cos(a) * rx) + up * (Mathf.Sin(a) * ry);
            }
        }

        for (int i = 0; i < n - 1; i++)
        {
            float v0 = i / (float)(n - 1) * 3.0f;
            float v1 = (i + 1) / (float)(n - 1) * 3.0f;
            for (int r = 0; r < ringSegs; r++)
            {
                int rn = (r + 1) % ringSegs;
                float u0 = r / (float)ringSegs;
                float u1 = (r + 1) / (float)ringSegs;

                Vector3 p00 = rings[i][r];
                Vector3 p01 = rings[i][rn];
                Vector3 p11 = rings[i + 1][rn];
                Vector3 p10 = rings[i + 1][r];
                Vector3 midRing = (path[i] + path[i + 1]) * 0.5f;
                Vector3 quadCenter = (p00 + p01 + p11 + p10) * 0.25f;
                AddOrientedQuad(st, p00, p10, p11, p01, new Vector2(u0, v0), new Vector2(u0, v1), new Vector2(u1, v1), new Vector2(u1, v0), quadCenter - midRing);
            }
        }

        st.GenerateNormals();
        st.GenerateTangents();
        return st.Commit();
    }

    /// <summary>
    /// Creates a sculpted, tapered 3D F1 nosecone & curved upper monocoque deck.
    /// </summary>
    public static ArrayMesh CreateSculptedNoseconeMesh()
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        // Stations from cockpit front (-0.72) forward to tapered nose tip (-3.05)
        // (z, halfWidth, topY, botY, crownHeight)
        (float z, float hw, float topY, float botY, float crown)[] stations =
        {
            (-0.68f, 0.44f, 0.63f, 0.24f, 0.055f),
            (-1.05f, 0.39f, 0.60f, 0.22f, 0.055f),
            (-1.55f, 0.31f, 0.52f, 0.20f, 0.050f),
            (-2.10f, 0.23f, 0.42f, 0.18f, 0.042f),
            (-2.65f, 0.15f, 0.31f, 0.17f, 0.030f),
            (-3.05f, 0.09f, 0.22f, 0.16f, 0.018f)
        };

        const int arcPts = 10; // Rounded upper deck cross-section from left bottom -> left top -> crown -> right top -> right bottom
        Vector3[][] rings = new Vector3[stations.Length][];

        for (int s = 0; s < stations.Length; s++)
        {
            var stn = stations[s];
            rings[s] = new Vector3[arcPts];
            for (int k = 0; k < arcPts; k++)
            {
                float t = k / (float)(arcPts - 1); // 0 = left lower, 0.5 = top center, 1 = right lower
                float ang = Mathf.Pi * (1.0f - t); // Pi -> 0
                float x = Mathf.Cos(ang) * stn.hw;
                float sinA = Mathf.Sin(ang);
                float y = stn.botY + (stn.topY - stn.botY) * Mathf.Pow(sinA, 0.55f) + stn.crown * Mathf.Pow(sinA, 2.0f);
                rings[s][k] = new Vector3(x, y, stn.z);
            }
        }

        for (int s = 0; s < stations.Length - 1; s++)
        {
            float v0 = s / (float)(stations.Length - 1);
            float v1 = (s + 1) / (float)(stations.Length - 1);
            Vector3 center = new Vector3(0f, 0.20f, (stations[s].z + stations[s + 1].z) * 0.5f);
            for (int k = 0; k < arcPts - 1; k++)
            {
                float u0 = k / (float)(arcPts - 1);
                float u1 = (k + 1) / (float)(arcPts - 1);
                Vector3 a = rings[s][k];
                Vector3 b = rings[s + 1][k];
                Vector3 c = rings[s + 1][k + 1];
                Vector3 d = rings[s][k + 1];
                Vector3 mid = (a + b + c + d) * 0.25f;
                AddOrientedQuad(st, a, b, c, d, new Vector2(u0, v0), new Vector2(u0, v1), new Vector2(u1, v1), new Vector2(u1, v0), mid - center);
            }
        }

        // Front nose tip cap
        var last = rings[stations.Length - 1];
        Vector3 tipCenter = new Vector3(0f, 0.19f, -3.12f);
        for (int k = 0; k < arcPts - 1; k++)
        {
            Vector3 p0 = last[k];
            Vector3 p1 = last[k + 1];
            Vector3 triN = (p1 - tipCenter).Cross(p0 - tipCenter);
            if (triN.Dot(Vector3.Forward) >= 0f)
            {
                st.SetUV(new Vector2(0.5f, 1f)); st.AddVertex(tipCenter);
                st.SetUV(new Vector2(0.4f, 0.9f)); st.AddVertex(p0);
                st.SetUV(new Vector2(0.6f, 0.9f)); st.AddVertex(p1);
            }
            else
            {
                st.SetUV(new Vector2(0.5f, 1f)); st.AddVertex(tipCenter);
                st.SetUV(new Vector2(0.6f, 0.9f)); st.AddVertex(p1);
                st.SetUV(new Vector2(0.4f, 0.9f)); st.AddVertex(p0);
            }
        }

        st.GenerateNormals();
        st.GenerateTangents();
        return st.Commit();
    }

    /// <summary>
    /// Creates an extruded 3D F1 butterfly carbon steering wheel faceplate (in XY plane, thickness along Z).
    /// </summary>
    public static ArrayMesh CreateButterflyWheelMesh(float halfW, float halfH, float thickness)
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        // Authentic F1 butterfly outline (ordered counter-clockwise in XY when looking from +Z)
        Vector2[] poly =
        {
            new Vector2(-0.88f * halfW,  0.96f * halfH), // Top-left ear
            new Vector2(-1.02f * halfW,  0.58f * halfH), // Upper-left grip bulge
            new Vector2(-0.96f * halfW, -0.58f * halfH), // Lower-left grip
            new Vector2(-0.76f * halfW, -0.96f * halfH), // Bottom-left corner
            new Vector2( 0.76f * halfW, -0.96f * halfH), // Bottom-right corner
            new Vector2( 0.96f * halfW, -0.58f * halfH), // Lower-right grip
            new Vector2( 1.02f * halfW,  0.58f * halfH), // Upper-right grip bulge
            new Vector2( 0.88f * halfW,  0.96f * halfH), // Top-right ear
            new Vector2( 0.46f * halfW,  0.96f * halfH), // Top-right inner shoulder
            new Vector2( 0.36f * halfW,  0.80f * halfH), // Top brow cutout right
            new Vector2(-0.36f * halfW,  0.80f * halfH), // Top brow cutout left
            new Vector2(-0.46f * halfW,  0.96f * halfH)  // Top-left inner shoulder
        };

        float zFront = thickness * 0.5f;
        float zBack = -thickness * 0.5f;
        Vector3 cFront = new Vector3(0f, 0f, zFront);
        Vector3 cBack = new Vector3(0f, 0f, zBack);
        Vector2 uvMid = new Vector2(0.5f, 0.5f);

        int n = poly.Length;
        for (int i = 0; i < n; i++)
        {
            Vector2 p0 = poly[i];
            Vector2 p1 = poly[(i + 1) % n];

            Vector3 f0 = new Vector3(p0.X, p0.Y, zFront);
            Vector3 f1 = new Vector3(p1.X, p1.Y, zFront);
            Vector3 b0 = new Vector3(p0.X, p0.Y, zBack);
            Vector3 b1 = new Vector3(p1.X, p1.Y, zBack);

            Vector2 uv0 = new Vector2(p0.X / (halfW * 2f) + 0.5f, 0.5f - p0.Y / (halfH * 2f));
            Vector2 uv1 = new Vector2(p1.X / (halfW * 2f) + 0.5f, 0.5f - p1.Y / (halfH * 2f));

            // Front face (+Z)
            Vector3 nF = (f1 - cFront).Cross(f0 - cFront);
            if (nF.Dot(Vector3.Back) >= 0f) // Vector3.Back == (0,0,+1) in Godot!
            {
                st.SetUV(uvMid); st.AddVertex(cFront);
                st.SetUV(uv0); st.AddVertex(f0);
                st.SetUV(uv1); st.AddVertex(f1);
            }
            else
            {
                st.SetUV(uvMid); st.AddVertex(cFront);
                st.SetUV(uv1); st.AddVertex(f1);
                st.SetUV(uv0); st.AddVertex(f0);
            }

            // Back face (-Z)
            Vector3 nB = (b1 - cBack).Cross(b0 - cBack);
            if (nB.Dot(Vector3.Forward) >= 0f) // Vector3.Forward == (0,0,-1)
            {
                st.SetUV(uvMid); st.AddVertex(cBack);
                st.SetUV(uv0); st.AddVertex(b0);
                st.SetUV(uv1); st.AddVertex(b1);
            }
            else
            {
                st.SetUV(uvMid); st.AddVertex(cBack);
                st.SetUV(uv1); st.AddVertex(b1);
                st.SetUV(uv0); st.AddVertex(b0);
            }

            // Extruded outer rim wall
            Vector2 edgeMid = (p0 + p1) * 0.5f;
            Vector3 outDir = new Vector3(edgeMid.X, edgeMid.Y, 0f).Normalized();
            AddOrientedQuad(st, f0, f1, b1, b0, new Vector2(0f, 0f), new Vector2(1f, 0f), new Vector2(1f, 1f), new Vector2(0f, 1f), outDir);
        }

        st.GenerateNormals();
        st.GenerateTangents();
        return st.Commit();
    }
}

