    private void BuildRacingGlove3D(float side, StandardMaterial3D carbonMat, StandardMaterial3D whiteCuffMat)
    {
        var hand = new Node3D { Position = new Vector3(side * 0.152f, -0.012f, 0.010f) };
        AddChild(hand);

        // Sculpted ergonomic palm & back-of-hand shell
        hand.AddChild(new MeshInstance3D
        {
            Mesh = new CapsuleMesh { Radius = 0.032f, Height = 0.105f, RadialSegments = 14, Rings = 6 },
            Position = new Vector3(side * 0.008f, -0.008f, 0.008f),
            RotationDegrees = new Vector3(14f, side * -12f, side * 10f),
            Scale = new Vector3(0.92f, 1.0f, 0.78f),
            MaterialOverride = _gloveMat
        });

        // Molded dark carbon knuckle guard on back of hand
        hand.AddChild(new MeshInstance3D
        {
            Mesh = new BoxMesh { Size = new Vector3(0.044f, 0.022f, 0.012f) },
            Position = new Vector3(side * 0.006f, 0.012f, 0.029f),
            RotationDegrees = new Vector3(0f, side * -12f, side * 8f),
            MaterialOverride = carbonMat
        });

        // 3 Wrapped Fingers curling around outer top/mid wheel grip
        for (int f = 0; f < 3; f++)
        {
            hand.AddChild(new MeshInstance3D
            {
                Mesh = new CapsuleMesh { Radius = 0.0115f, Height = 0.056f, RadialSegments = 10, Rings = 4 },
                Position = new Vector3(-side * 0.010f, 0.028f - f * 0.022f, -0.004f),
                RotationDegrees = new Vector3(0f, side * 18f, 90f),
                MaterialOverride = _gloveMat
            });
        }

        // Articulated Thumb wrapping inward toward DIFF/TORQ & top buttons
        hand.AddChild(new MeshInstance3D
        {
            Mesh = new CapsuleMesh { Radius = 0.014f, Height = 0.058f, RadialSegments = 10, Rings = 4 },
            Position = new Vector3(-side * 0.022f, 0.038f, 0.020f),
            RotationDegrees = new Vector3(-18f, side * 26f, side * 56f),
            MaterialOverride = _gloveMat
        });

        // Crisp White Nomex Elastic Wrist Cuff Band (exact signature detail from reference photo!)
        hand.AddChild(new MeshInstance3D
        {
            Mesh = new CylinderMesh { TopRadius = 0.029f, BottomRadius = 0.033f, Height = 0.034f, RadialSegments = 14 },
            Position = new Vector3(side * 0.022f, -0.068f, 0.030f),
            RotationDegrees = new Vector3(36f, 0f, side * 18f),
            MaterialOverride = whiteCuffMat
        });

        // Fireproof Racing Suit Forearm extending organically down into the cockpit
        hand.AddChild(new MeshInstance3D
        {
            Mesh = new CylinderMesh { TopRadius = 0.033f, BottomRadius = 0.044f, Height = 0.22f, RadialSegments = 14 },
            Position = new Vector3(side * 0.058f, -0.155f, 0.105f),
            RotationDegrees = new Vector3(44f, 0f, side * 22f),
            MaterialOverride = _sleeveMat
        });
    }

    public void UpdateColors(Color gloveColor, Color suitColor)
    {
        if (_gloveMat != null) _gloveMat.AlbedoColor = gloveColor;
        if (_sleeveMat != null) _sleeveMat.AlbedoColor = suitColor;
    }

    public void UpdateTelemetry(
        float dt,
        float speedKmh,
        int gear,
        float rpmNorm,
        float lapTime,
        float bestLap,
        float ersCharge,
        bool ersActive,
        bool offTrack,
        float tireHeat,
        float totalTime)
    {
        // Trigger gear shift paddle kick animation on gear change
        if (gear != _prevGear && speedKmh > 25f)
        {
            _shiftWasUp = gear > _prevGear;
            _shiftKickTimer = 0.15f;
            _prevGear = gear;
        }
        if (_shiftKickTimer > 0f)
        {
            _shiftKickTimer = Mathf.Max(0f, _shiftKickTimer - dt);
        }

        float kick = _shiftKickTimer > 0f ? Mathf.Sin((_shiftKickTimer / 0.15f) * Mathf.Pi) * 14f : 0f;
        _paddleLeft.RotationDegrees = new Vector3(0f, !_shiftWasUp ? kick : 0f, 0f);
        _paddleRight.RotationDegrees = new Vector3(0f, _shiftWasUp ? -kick : 0f, 0f);

        // 15-LED Shift Light Bar (5 Green -> 5 Red -> 5 Blue, flashing at redline!)
        bool redlineFlash = rpmNorm > 0.93f && (((int)(totalTime * 16f) % 2) == 0);
        for (int i = 0; i < ShiftLedCount; i++)
        {
            bool lit = redlineFlash || ((i / (float)ShiftLedCount) < rpmNorm && speedKmh > 5f);
            Color c = i < 5 ? new Color(0.05f, 0.95f, 0.42f) : (i < 10 ? new Color(1.0f, 0.12f, 0.16f) : new Color(0.18f, 0.52f, 1.0f));
            _rpmLedMats[i].AlbedoColor = lit ? c : new Color(0.10f, 0.12f, 0.16f);
            _rpmLedMats[i].Emission = lit ? c : Colors.Black;
        }

        // Flanking 6 FIA Marshal / ERS LEDs
        Color flagCol = offTrack
            ? new Color(1.0f, 0.72f, 0.0f)
            : (ersActive ? new Color(0.0f, 0.92f, 1.0f) : new Color(0.05f, 0.85f, 0.42f));
        bool flagLit = offTrack || ersActive || speedKmh > 40f;
        for (int i = 0; i < _flagLedMats.Length; i++)
        {
            _flagLedMats[i].AlbedoColor = flagLit ? flagCol : new Color(0.10f, 0.12f, 0.16f);
            _flagLedMats[i].Emission = flagLit ? flagCol : Colors.Black;
        }

        // Live 512x288 OLED MFD Contents
        _mfdKph.Text = $"{(int)speedKmh}";
        _mfdLap.Text = lapTime < 60f
            ? $"{lapTime:00.000}"
            : $"{(int)(lapTime / 60f)}:{(lapTime % 60f):00.00}";
        _mfdGear.Text = $"{gear}";
        _mfdGear.AddThemeColorOverride("font_color", redlineFlash ? new Color(0.45f, 0.88f, 1.0f) : Colors.White);

        if (bestLap < 900f)
        {
            float d = lapTime - bestLap;
            _mfdDelta.Text = d >= 0f ? $"+{d:0.00}" : $"{d:0.00}";
            _mfdDelta.AddThemeColorOverride("font_color", d <= 0f ? new Color(0.15f, 0.96f, 0.48f) : new Color(1.0f, 0.36f, 0.30f));
        }
        else
        {
            _mfdDelta.Text = "LIVE";
        }

        int fTemp = Mathf.RoundToInt(84f + tireHeat * 22f);
        int rTemp = Mathf.RoundToInt(87f + tireHeat * 20f);
        Color tCol = tireHeat > 0.75f ? new Color(1.0f, 0.78f, 0.32f) : new Color(0.90f, 0.97f, 0.92f);
        _mfdTempFL.Text = $"{fTemp}°C";
        _mfdTempFR.Text = $"{fTemp}°C";
        _mfdTempRL.Text = $"{rTemp}°C";
        _mfdTempRR.Text = $"{rTemp}°C";
        _mfdTempFL.AddThemeColorOverride("font_color", tCol);
        _mfdTempFR.AddThemeColorOverride("font_color", tCol);
        _mfdTempRL.AddThemeColorOverride("font_color", tCol);
        _mfdTempRR.AddThemeColorOverride("font_color", tCol);

        // Authentic 3-Zone Segmented F1 OVERTAKE Bar
        float frac = Mathf.Clamp(ersCharge / 100f, 0f, 1f);
        float totalW = 488f * frac;
        if (ersActive)
        {
            _ovtZoneRed.Visible = false;
            _ovtZoneYellow.Visible = false;
            _ovtZoneGreen.Visible = false;
            _ovtZoneCyan.Visible = true;
            _ovtZoneCyan.Size = new Vector2(Mathf.Max(4f, totalW), 62f);
        }
        else
        {
            _ovtZoneCyan.Visible = false;
            float w1 = Mathf.Min(totalW, 98f);
            float w2 = Mathf.Max(0f, Mathf.Min(totalW, 378f) - 98f);
            float w3 = Mathf.Max(0f, totalW - 378f);
            _ovtZoneRed.Visible = w1 > 1f;
            _ovtZoneYellow.Visible = w2 > 1f;
            _ovtZoneGreen.Visible = w3 > 1f;
            _ovtZoneRed.Size = new Vector2(w1, 62f);
            _ovtZoneYellow.Size = new Vector2(w2, 62f);
            _ovtZoneGreen.Size = new Vector2(w3, 62f);
        }

        _mfdOvtText.Text = offTrack
            ? "TRACK LIMITS"
            : (ersActive ? $"OVERTAKE ON  {(int)ersCharge}%" : $"OVERTAKE  {(int)ersCharge}%");
        _mfdOvtText.AddThemeColorOverride("font_color", frac > 0.24f ? new Color(0.04f, 0.06f, 0.10f) : Colors.White);
    }
